CREATE TRIGGER closed_account_receipt BEFORE INSERT ON upload_receipts WHEN EXISTS(SELECT 1 FROM account_deletions WHERE owner_id=new.owner_id) OR EXISTS(SELECT 1 FROM project_lifecycle WHERE project_id=new.project_id AND state='deleting') BEGIN SELECT RAISE(ABORT,'Upload account or project is closed'); END;
CREATE TRIGGER closed_account_source BEFORE INSERT ON sources WHEN EXISTS(SELECT 1 FROM upload_receipts r JOIN account_deletions d ON d.owner_id=r.owner_id WHERE r.id=new.id) OR EXISTS(SELECT 1 FROM upload_reservations r JOIN account_deletions d ON d.owner_id=r.owner_id WHERE r.id=new.id) OR EXISTS(SELECT 1 FROM project_lifecycle WHERE project_id=new.project_id AND state='deleting') BEGIN SELECT RAISE(ABORT,'Upload account or project is closed'); END;
CREATE TABLE object_cleanup(id TEXT PRIMARY KEY, path TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL);
